Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Baterias por mês · barra = período, traço = mesmo mês do ano anterior"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "datum[''Status''] == ''Parcial''",
      "as": "parcial"
    }
  ],
  "encoding": {
    "x": {
      "field": "Mes",
      "type": "ordinal",
      "timeUnit": "yearmonth",
      "axis": {
        "format": "%b/%y",
        "title": null,
        "labelAngle": 0,
        "labelOverlap": "greedy"
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusTopLeft": 3,
        "cornerRadiusTopRight": 3,
        "width": {
          "band": 0.62
        }
      },
      "encoding": {
        "y": {
          "field": "Qtd",
          "type": "quantitative",
          "axis": {
            "title": null,
            "format": "~s",
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "tickCount": 4
          }
        },
        "color": {
          "condition": {
            "test": "datum.parcial",
            "value": "#3A2A16"
          },
          "value": "#FF8C00"
        },
        "stroke": {
          "condition": {
            "test": "datum.parcial",
            "value": "#FF8C00"
          },
          "value": null
        },
        "strokeDash": {
          "value": [
            3,
            2
          ]
        },
        "tooltip": [
          {
            "field": "Mes",
            "type": "ordinal",
            "timeUnit": "yearmonth",
            "format": "%B/%Y",
            "title": "Mês"
          },
          {
            "field": "Status",
            "title": "Situação"
          },
          {
            "field": "Qtd",
            "format": ",.0f",
            "title": "Baterias"
          },
          {
            "field": "QtdAA",
            "format": ",.0f",
            "title": "Ano anterior"
          },
          {
            "field": "Var",
            "format": "+.1%",
            "title": "Variação"
          },
          {
            "field": "Fat",
            "format": ",.0f",
            "title": "Faturamento (R$)"
          },
          {
            "field": "Cob",
            "format": ".1%",
            "title": "Cobertura"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#F2F4F5",
        "thickness": 2,
        "size": 22,
        "opacity": 0.9
      },
      "encoding": {
        "y": {
          "field": "QtdAA",
          "type": "quantitative"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum[''Var'']) && !datum.parcial"
        }
      ],
      "mark": {
        "type": "text",
        "dy": -10,
        "fontSize": 10,
        "fontWeight": 600
      },
      "encoding": {
        "y": {
          "field": "Qtd",
          "type": "quantitative"
        },
        "text": {
          "field": "Var",
          "format": "+.0%"
        },
        "color": {
          "condition": {
            "test": "datum[''Var''] < 0",
            "value": "#FF6B6F"
          },
          "value": "#3FB68B"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.parcial"
        }
      ],
      "mark": {
        "type": "text",
        "dy": -10,
        "fontSize": 10,
        "color": "#FFB45C",
        "text": "parcial"
      },
      "encoding": {
        "y": {
          "field": "Qtd",
          "type": "quantitative"
        }
      }
    }
  ]
}'
